// Generated by Cypress Author on 2026-11-18

describe('Site Navigation Flows', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('click Contact link in header → navigates to /contact view', () => {
    cy.get('dml-header-nav').contains('a', 'Contact').click();

    cy.url().should('include', '/contact');
    cy.get('dm-contact').should('be.visible');
    cy.get('dm-contact').contains('h1', 'Get in Touch').should('be.visible');
  });

  it('click About link in header → navigates to /about dynamic page', () => {
    cy.get('dml-header-nav').contains('a', 'About').click();

    cy.url().should('include', '/about');
    cy.get('dm-dynamic-page').should('be.visible');
    cy.get('dm-dynamic-page').contains('h1', 'About Delisha Marie').should('be.visible');
  });

  it('click site logo from sub-page → returns to home view', () => {
    cy.visit('/contact');
    cy.get('dm-contact').should('be.visible');

    cy.get('dml-header-logo a').click();

    cy.url().should('eq', `${Cypress.config().baseUrl}/`);
    cy.get('dm-home').should('be.visible');
  });

  it('verify Kitchen navigation links → contain external link target', () => {
    cy.get('dml-header-nav')
      .contains('a', 'Kitchen')
      .should('have.attr', 'href')
      .and('not.be.empty');

    cy.get('dm-footer').contains('a', 'Kitchen').should('have.attr', 'href').and('not.be.empty');
  });

  it('click Contact link in footer → navigates to /contact', () => {
    cy.get('dm-footer').contains('a', 'Contact').click();

    cy.url().should('include', '/contact');
    cy.get('dm-contact').should('be.visible');
  });

  it('click About link in footer → navigates to /about', () => {
    cy.get('dm-footer').contains('a', 'About').click();

    cy.url().should('include', '/about');
    cy.get('dm-dynamic-page').should('be.visible');
  });

  it('navigate to nested unrecognized route → redirects back to home /', () => {
    cy.visit('/unknown/nested/route');

    cy.url().should('eq', `${Cypress.config().baseUrl}/`);
    cy.get('dm-home').should('be.visible');
  });
});
